from lib import *
S = SS('u164')
R = J('u164'); C = R['cost']; N = C['原生 -O']; A_ = C['ASan -O']
lr = A_['loop'] / N['loop']; ar = A_['alloc'] / N['alloc']; mr = A_['rss'] / N['rss']
steps = [
    step("释放后使用:ASan 编译(-Zsanitizer=address)的程序遇到 drop 之后的读取,立刻 abort,报「heap-use-after-free」,并给出三份调用栈:读取发生在 u164_uaf.rs:5;内存「0 bytes inside of 12-byte region」(3 个 i32);「freed by」栈指向 RawVec 的 drop;「previously allocated by」栈指向 alloc。SUMMARY 行直接给出出错的源码行。对比 Miri:这里不需要解释执行,是原生速度的程序加了运行时检查。", t=tl(S(1)), mark=lidx(S(1), 'heap-use-after-free', 'freed by', 'previously allocated by', 'SUMMARY'), kv=KV([['错误类型', 'heap-use-after-free'], ['区域', '12-byte region'], ['定位', 'u164_uaf.rs:5']], ['错误类型'])),
    step("堆越界读:读第 4 个 u32 时报「heap-buffer-overflow」,「located 0 bytes after 12-byte region」,即刚好越过 12 字节分配的末尾。对照安全代码 v[3]:不需要 sanitizer,直接 panic「index out of bounds: the len is 3 but the index is 3」,退出码 101。sanitizer 针对的是 unsafe 绕过了安全检查的访问。", t=tl(S(2)), mark=lidx(S(2), 'heap-buffer-overflow', '0 bytes after', 'index out of bounds'), kv=KV([['unsafe 越界', 'ASan:heap-buffer-overflow(abort)'], ['安全下标越界', 'panic,退出码 101']], ['unsafe 越界'])),
    step("栈越界:读长度为 4 的数组 a 之后的 1 字节,ASan 报「stack-buffer-overflow」,并列出栈帧里的变量:[80, 84) 'a' (line 3),注明「Memory access at offset 84 overflows this variable」。重复释放:对同一个裸指针 Box::from_raw 两次,报「attempting double-free」,同样给出 freed by 与 previously allocated by 两份栈。", t=tl(S(3)), mark=lidx(S(3), 'stack-buffer-overflow', 'overflows this variable', 'double-free'), kv=KV([['栈越界', "定位到变量 'a' (line 3)"], ['重复释放', 'attempting double-free']], ['栈越界'])),
    step("泄漏:ASan 在本机(macOS arm64)上、设 ASAN_OPTIONS=detect_leaks=1 时,程序退出时给出「LeakSanitizer: detected memory leaks」:Direct leak of 16 byte(s) in 1 object(s),退出码 1;程序自己的 done 照常打印。而单独的 -Zsanitizer=leak 与 -Zsanitizer=memory 在本机的编译器上都报「not supported for this target」。", t=tl(S(4)), mark=lidx(S(4), 'detected memory leaks', 'Direct leak', 'not supported'), kv=KV([['address + detect_leaks=1', '能报 16 字节泄漏'], ['-Zsanitizer=leak', 'not supported for this target'], ['-Zsanitizer=memory', 'not supported for this target']], ['address + detect_leaks=1'])),
    step("C 函数造成的越界:Rust 调用 libc 的 memcpy 往 8 字节的 Vec 写 16 字节。ASan 拦截了 memcpy,报「heap-buffer-overflow」「WRITE of size 16」「0 bytes after 8-byte region」,调用栈第一帧是 memcpy,第二帧是出错的 u164_ffi.rs:6。上一篇 Miri 对外部 C 函数 ffs 直接报不支持,而 sanitizer 在原生代码里运行,没有这个限制。(没有验证:Miri 对 memcpy 本身的处理,本篇没有跑。)", t=tl(S(5)), mark=lidx(S(5), 'heap-buffer-overflow', 'WRITE of size 16', 'memcpy+'), kv=KV([['写入', 'WRITE of size 16'], ['区域', '8-byte region'], ['来源', 'libc memcpy ← u164_ffi.rs:6']], ['来源'])),
    step(f"ThreadSanitizer 检测数据竞争,但有额外要求:只给自己的 crate 加 -Zsanitizer=thread,编译直接失败「mixing `-Zsanitizer` will cause an ABI mismatch in crate `ts`」(标准库没有用同一个选项编译),退出码 101。加上 -Zbuild-std 重新编译标准库(这次共 {R['tsan']['secs']} 秒)后可以运行:报 2 个「data race」,一个是子线程 main.rs:9 的读与主线程 main.rs:11 的写,一个是两个线程各自的写;最后「reported 2 warnings」。注意这次运行程序自己打印的结果是 x = 2000(竞争存在,结果碰巧对)。", t=tl(S(6)), mark=lidx(S(6), 'ABI mismatch', 'WARNING: ThreadSanitizer: data race', 'reported 2 warnings'), done=lidx(S(6), 'x = 2000'), kv=KV([['不重编 std', 'ABI mismatch,编译失败'], ['-Zbuild-std', f"{R['tsan']['secs']} 秒;2 个 data race"]], ['-Zbuild-std'])),
    step(f"代价(-O,7 次取中位数):遍历 2000 万个元素 {N['loop']:.1f} ms → ASan {A_['loop']:.1f} ms(×{lr:.1f});200 万次 Box::new {N['alloc']:.1f} ms → {A_['alloc']:.1f} ms(×{ar:.1f});峰值内存 {N['rss']:.0f} MiB → {A_['rss']:.0f} MiB(×{mr:.1f});可执行文件 {N['size'] / 1024:.0f} KiB 对 {A_['size'] / 1024:.0f} KiB(ASan 运行库是动态链接的 librustc-nightly_rt.asan.dylib,不在可执行文件里)。分配密集的程序更慢,因为每次 malloc/free 都要维护隔离区与红区。与上一篇 Miri 慢约 3 万倍相比,开销小得多。", t=tl(S(7)), b=bars([['遍历 原生', N['loop'], f"{N['loop']:.1f} ms"], ['遍历 ASan', A_['loop'], f"{A_['loop']:.1f} ms"], ['分配 原生', N['alloc'], f"{N['alloc']:.1f} ms"], ['分配 ASan', A_['alloc'], f"{A_['alloc']:.1f} ms"]], A_['alloc'], done=[0, 1, 2, 3]), kv=KV([['遍历', f'×{lr:.1f}'], ['200 万次分配', f'×{ar:.1f}'], ['峰值内存', f'×{mr:.1f}']], ['200 万次分配'])),
]
A = mkart('u164', 164, 'Rust,Sanitizer,AddressSanitizer,ThreadSanitizer,真实验证,动画演示',
    f'用 nightly 的 -Zsanitizer 验证:ASan 在原生速度上报告释放后使用、堆/栈越界、重复释放、泄漏(本机 detect_leaks=1 可用)与 libc memcpy 越界;TSan 需要 -Zbuild-std 才能报数据竞争;-Zsanitizer=leak/memory 在本机不支持;开销:分配密集场景 ×{ar:.1f},遍历 ×{lr:.1f},内存 ×{mr:.1f}。',
    '上一篇的 Miri 能解释执行但很慢,也不能调 C 函数。Sanitizer 换了一条路:编译时在原生代码里插入检查,运行得快得多。这篇把常见的内存错误和数据竞争各跑一遍,看它们的报告长什么样、哪些在本机能用、代价多大。',
    [('5', '本篇用 ASan 触发并报告的内存错误种类(释放后使用、堆越界、栈越界、重复释放、泄漏;另有 memcpy 越界)'), (f'×{ar:.1f}', '200 万次 Box::new:ASan 对原生 -O 的耗时倍数'), ('2', '本机不支持的 -Zsanitizer 值:leak、memory')],
    [('释放后使用', '<p>对比解释执行的 Miri 见<a href="rust-miri.html">Miri 检查未定义行为</a>。</p>'), ('堆越界读', None), ('栈越界与重复释放', None), ('泄漏', None), ('外部 C 函数', None), ('ThreadSanitizer', '<p>数据竞争在安全代码里是编译错误,见<a href="rust-data-race-compile-error.html">数据竞争为什么编译不过</a>;这里为了触发它用了 unsafe 的裸指针。</p>'), ('代价', '<p>模糊测试通常与 sanitizer 一起运行,见<a href="rust-fuzz.html">Fuzz 测试</a>。</p>')],
    steps, [ENV_N + '。-Zsanitizer=address(直接用 rustc);-Zsanitizer=thread 配合 cargo -Zbuild-std(rust-src 组件);栈符号用 -Zunstable-options -C symbol-mangling-version=legacy 以便阅读', '没有验证:Linux 上的 sanitizer 行为与支持范围(例如 leak、memory)、-Zbuild-std 对 ASan 的影响(本篇的 ASan 没有重编标准库,因此标准库内部代码没有被插桩)、stack-use-after-return 与 stack-use-after-scope、ASAN_OPTIONS 的其它选项、sanitizer 与 Miri 同时使用', '本篇的调用栈只截取了前 3 帧、省略了 Shadow bytes 部分以便阅读;其余内容为原样输出'], 'Sanitizer')
